# ============================================================
# 020_Figure_ControlStress_PCA_Ellipses95.R
#
# Objective 2
# Control versus Stress projection with 95% normal-theory data ellipses
#
# Corrected upstream dependency:
#   03_Results/Objects/
#   objective2_control_stress_pca_results_robust.rds
#
# This object is generated by the corrected Script 019 and already
# contains the corrected Objective 1 PC1-PC2 coordinate system,
# the projected Control and Stress scores, Author + ID traceability,
# the within-Author robust-normalisation metadata, the group centroids,
# and the inherited explained variance.
#
# No PCA is refitted in this script.
#
# The ellipses are descriptive 95% normal-theory data ellipses:
#   (x - mean)' S^(-1) (x - mean) = qchisq(0.95, df = 2)
#
# They summarise the centre, orientation, and covariance of each
# independent population in the PC1-PC2 plane. They are not 95%
# confidence regions for the group centroids and are not used as an
# inferential test of group separation or dispersion.
# ============================================================

# ------------------------------------------------------------
# 1. Project directory
# ------------------------------------------------------------

project_root <- normalizePath(
  Sys.getenv(
    "LAPCOM_UCS_PROJECT_ROOT",
    unset = getwd()
  ),
  winslash = "/",
  mustWork = TRUE
)

if (!dir.exists(project_root)) {
  stop(
    "Project directory not found:\n",
    project_root
  )
}

setwd(project_root)

# ------------------------------------------------------------
# 2. Required packages
# ------------------------------------------------------------

required_packages <- c(
  "dplyr",
  "tibble",
  "ggplot2"
)

missing_packages <- required_packages[
  !vapply(
    required_packages,
    requireNamespace,
    logical(1),
    quietly = TRUE
  )
]

if (length(missing_packages) > 0L) {
  stop(
    "Install the following packages before running this script:\n",
    paste(missing_packages, collapse = ", ")
  )
}

library(dplyr)
library(tibble)
library(ggplot2)

# ------------------------------------------------------------
# 3. Fixed settings
# ------------------------------------------------------------

required_treatments <- c(
  "Control",
  "Stress"
)

expected_control_n <- 89L
expected_stress_n <- 89L
expected_number_of_authors <- 4L

expected_traceability <- "Author + ID"
expected_normalisation <-
  "Within Author: (x - median) / (1.4826 x raw MAD)"

ellipse_level <- 0.95
ellipse_segments <- 361L

numeric_tolerance <- 1e-10
projection_tolerance <- 1e-8

if (
  length(ellipse_level) != 1L ||
  !is.finite(ellipse_level) ||
  ellipse_level <= 0 ||
  ellipse_level >= 1
) {
  stop(
    "ellipse_level must be a single finite value between 0 and 1."
  )
}

if (
  length(ellipse_segments) != 1L ||
  !is.finite(ellipse_segments) ||
  ellipse_segments < 100L ||
  ellipse_segments != as.integer(ellipse_segments)
) {
  stop(
    "ellipse_segments must be an integer of at least 100."
  )
}

ellipse_critical_value <- stats::qchisq(
  p = ellipse_level,
  df = 2
)

ellipse_radius <- sqrt(
  ellipse_critical_value
)

if (
  !is.finite(ellipse_critical_value) ||
  ellipse_critical_value <= 0 ||
  !is.finite(ellipse_radius) ||
  ellipse_radius <= 0
) {
  stop(
    "The 95% ellipse critical value could not be calculated."
  )
}

# ------------------------------------------------------------
# 4. Input and output paths
# ------------------------------------------------------------

objects_dir <- file.path(
  project_root,
  "03_Results",
  "Objects"
)

tables_dir <- file.path(
  project_root,
  "03_Results",
  "Tables"
)

figures_dir <- file.path(
  project_root,
  "03_Results",
  "Figures"
)

for (directory_i in c(
  objects_dir,
  tables_dir,
  figures_dir
)) {
  if (!dir.exists(directory_i)) {
    dir.create(
      directory_i,
      recursive = TRUE
    )
  }
}

script019_results_file <- file.path(
  objects_dir,
  "objective2_control_stress_pca_results_robust.rds"
)

if (!file.exists(script019_results_file)) {
  stop(
    "Required Script 019 result object not found:\n",
    script019_results_file,
    "\nRun the corrected Script 019 before this script."
  )
}

ellipse_coordinates_output <- file.path(
  objects_dir,
  "objective2_control_stress_pca_ellipses95_coordinates.rds"
)

ellipse_plot_output <- file.path(
  objects_dir,
  "objective2_control_stress_pca_ellipses95_plot.rds"
)

ellipse_results_output <- file.path(
  objects_dir,
  "objective2_control_stress_pca_ellipses95_results.rds"
)

ellipse_summary_csv_output <- file.path(
  tables_dir,
  "Objective2_ControlStress_PCA_Ellipses95_Summary.csv"
)

ellipse_covariance_csv_output <- file.path(
  tables_dir,
