)

# ------------------------------------------------------------
# 5. Load and validate the corrected Script 019 object
# ------------------------------------------------------------

script019_results <- readRDS(
  script019_results_file
)

if (!is.list(script019_results)) {
  stop(
    basename(script019_results_file),
    " does not contain the expected result list."
  )
}

required_result_fields <- c(
  "Comparison_design",
  "Traceability",
  "Normalisation",
  "Author_Treatment_counts",
  "Explained_variance",
  "Scores",
  "Centroids",
  "Projection_audit"
)

missing_result_fields <- setdiff(
  required_result_fields,
  names(script019_results)
)

if (length(missing_result_fields) > 0L) {
  stop(
    "The corrected Script 019 result object is missing:\n",
    paste(missing_result_fields, collapse = ", ")
  )
}

if (
  !identical(
    as.character(
      script019_results[["Comparison_design"]]
    ),
    "Independent Control and Stress populations"
  )
) {
  stop(
    "The Script 019 object does not describe the required independent-",
