  )
}

if (
  !identical(
    as.character(
      script019_results[["Traceability"]]
    ),
    expected_traceability
  )
) {
  stop(
    "The corrected Script 019 object does not use Author + ID ",
    "traceability."
  )
}

if (
  !identical(
    as.character(
      script019_results[["Normalisation"]]
    ),
    expected_normalisation
  )
) {
  stop(
    "The corrected Script 019 object does not use within-Author ",
