  )
}

pca_scores <- script019_results[["Scores"]]
stored_centroids <- script019_results[["Centroids"]]
variance_table <- script019_results[["Explained_variance"]]
projection_audit <- script019_results[["Projection_audit"]]
author_treatment_counts <- script019_results[["Author_Treatment_counts"]]

if (!is.data.frame(pca_scores)) {
  stop(
    "The Scores field in the Script 019 object is not a data frame."
  )
}

if (!is.data.frame(stored_centroids)) {
  stop(
    "The Centroids field in the Script 019 object is not a data frame."
  )
}

if (!is.data.frame(variance_table)) {
  stop(
    "The Explained_variance field in the Script 019 object is not ",
    "a data frame."
  )
}

if (!is.data.frame(projection_audit)) {
  stop(
    "The Projection_audit field in the Script 019 object is not ",
    "a data frame."
  )
}

if (!is.data.frame(author_treatment_counts)) {
  stop(
    "The Author_Treatment_counts field in the Script 019 object is ",
    "not a data frame."
  )
}

required_score_columns <- c(
  "Analysis_ID",
  "Traceability_ID",
  "Author",
  "ID",
  "Treatment",
  "PC1",
  "PC2"
)

missing_score_columns <- setdiff(
  required_score_columns,
  names(pca_scores)
)

if (length(missing_score_columns) > 0L) {
  stop(
    "The corrected Script 019 PCA score table is missing:\n",
    paste(missing_score_columns, collapse = ", ")
  )
}

required_centroid_columns <- c(
  "Treatment",
  "PC1",
  "PC2"
)

missing_centroid_columns <- setdiff(
  required_centroid_columns,
  names(stored_centroids)
)

if (length(missing_centroid_columns) > 0L) {
  stop(
    "The Script 019 centroid table is missing:\n",
    paste(missing_centroid_columns, collapse = ", ")
  )
}

required_variance_columns <- c(
  "Component",
  "Percentage_of_variance"
)

missing_variance_columns <- setdiff(
  required_variance_columns,
  names(variance_table)
)

if (length(missing_variance_columns) > 0L) {
  stop(
    "The Script 019 variance table is missing:\n",
    paste(missing_variance_columns, collapse = ", ")
