}

required_projection_audit_columns <- c(
  "Control_n",
  "Stress_n",
  "Maximum_Control_score_reconstruction_error"
)

missing_projection_audit_columns <- setdiff(
  required_projection_audit_columns,
  names(projection_audit)
)

if (length(missing_projection_audit_columns) > 0L) {
  stop(
