}

required_author_count_columns <- c(
  "Author",
  "Treatment",
  "n"
)

missing_author_count_columns <- setdiff(
  required_author_count_columns,
  names(author_treatment_counts)
)

if (length(missing_author_count_columns) > 0L) {
  stop(
    "The Script 019 Author-by-Treatment table is missing:\n",
    paste(missing_author_count_columns, collapse = ", ")
