  any(!is.finite(pca_scores[["PC2"]]))
) {
  stop(
    "The Script 019 PC1 or PC2 scores are not finite numeric values."
  )
}

pca_scores <- pca_scores %>%
  dplyr::mutate(
    Analysis_ID = trimws(
      as.character(Analysis_ID)
    ),
    Traceability_ID = trimws(
      as.character(Traceability_ID)
    ),
    Author = trimws(
      as.character(Author)
    ),
    ID = trimws(
      as.character(ID)
    ),
    Treatment = factor(
      as.character(Treatment),
      levels = required_treatments
    )
  )

expected_traceability_id <- paste(
  pca_scores$Author,
  pca_scores$ID,
  sep = " || "
)

expected_analysis_id <- paste(
  pca_scores$Treatment,
  pca_scores$Author,
  pca_scores$ID,
  sep = "_"
)

if (
  nrow(pca_scores) !=
    expected_control_n +
      expected_stress_n ||
  anyNA(
    pca_scores[
      c(
        "Analysis_ID",
        "Traceability_ID",
        "Author",
        "ID",
        "Treatment"
      )
    ]
  ) ||
  any(pca_scores$Analysis_ID == "") ||
  any(pca_scores$Traceability_ID == "") ||
  any(pca_scores$Author == "") ||
  any(pca_scores$ID == "") ||
  anyDuplicated(pca_scores$Analysis_ID) > 0L ||
  anyDuplicated(pca_scores$Traceability_ID) > 0L ||
  !identical(
    pca_scores$Traceability_ID,
    expected_traceability_id
  ) ||
  !identical(
    pca_scores$Analysis_ID,
    expected_analysis_id
  )
) {
