if (
  anyNA(group_count_values) ||
  group_count_values[["Control"]] != expected_control_n ||
  group_count_values[["Stress"]] != expected_stress_n
) {
  stop(
    "Expected 89 Control and 89 Stress PCA scores."
  )
}

