  dplyr::mutate(
    Author = trimws(
      as.character(Author)
    ),
    Treatment = factor(
      as.character(Treatment),
      levels = required_treatments
    ),
    n = as.integer(
      n
    )
  ) %>%
  dplyr::arrange(
    Author,
    Treatment
  )

author_treatment_counts_reconstructed <- pca_scores %>%
  dplyr::count(
    Author,
    Treatment,
    name = "n",
    .drop = FALSE
  ) %>%
  dplyr::arrange(
    Author,
    Treatment
  )

author_count_comparison <- all.equal(
  author_treatment_counts,
  author_treatment_counts_reconstructed,
  tolerance = 0,
  check.attributes = FALSE
)

if (
  nrow(author_treatment_counts) !=
    expected_number_of_authors *
      length(required_treatments) ||
  anyNA(author_treatment_counts) ||
  any(author_treatment_counts$n <= 0L) ||
  !isTRUE(author_count_comparison)
) {
  stop(
    "The Author-by-Treatment counts do not reproduce the corrected ",
    "Script 019 PCA scores."
  )
}

if (
  nrow(projection_audit) != 1L ||
  !is.numeric(projection_audit[["Control_n"]]) ||
  !is.numeric(projection_audit[["Stress_n"]]) ||
  !is.numeric(
    projection_audit[["Maximum_Control_score_reconstruction_error"]]
  )
) {
  stop(
    "The Script 019 projection audit has an invalid structure."
  )
}

if (
  projection_audit[["Control_n"]][1] != expected_control_n ||
  projection_audit[["Stress_n"]][1] != expected_stress_n ||
  !is.finite(
    projection_audit[["Maximum_Control_score_reconstruction_error"]][1]
  ) ||
  projection_audit[["Maximum_Control_score_reconstruction_error"]][1] >
    projection_tolerance
) {
  stop(
    "The corrected Script 019 projection audit does not confirm the ",
    "Control-reference projection."
  )
}

# ------------------------------------------------------------
# 6. Retrieve the inherited explained variance
# ------------------------------------------------------------

variance_table <- variance_table %>%
  dplyr::mutate(
    Component = as.character(Component),
    Percentage_of_variance = as.numeric(
      Percentage_of_variance
    )
  )

if (
  anyNA(variance_table[["Component"]]) ||
  any(variance_table[["Component"]] == "") ||
  anyNA(variance_table[["Percentage_of_variance"]]) ||
  any(!is.finite(variance_table[["Percentage_of_variance"]])) ||
  any(variance_table[["Percentage_of_variance"]] < 0) ||
  any(variance_table[["Percentage_of_variance"]] > 100) ||
  anyDuplicated(variance_table[["Component"]]) > 0L
) {
  stop(
    "The inherited explained-variance table is invalid."
  )
}

pc1_row <- variance_table[
  variance_table[["Component"]] == "PC1",
  ,
  drop = FALSE
]

pc2_row <- variance_table[
  variance_table[["Component"]] == "PC2",
  ,
  drop = FALSE
]

if (
  nrow(pc1_row) != 1L ||
  nrow(pc2_row) != 1L
) {
  stop(
    "PC1 or PC2 could not be identified uniquely in the inherited ",
    "variance table."
  )
}

pc1_percent <- as.numeric(
  pc1_row[["Percentage_of_variance"]][1]
)

pc2_percent <- as.numeric(
  pc2_row[["Percentage_of_variance"]][1]
)

pc12_percent <- pc1_percent + pc2_percent

if (
  !is.finite(pc1_percent) ||
  !is.finite(pc2_percent) ||
  !is.finite(pc12_percent) ||
  pc1_percent <= 0 ||
  pc2_percent <= 0 ||
  pc12_percent > 100 + numeric_tolerance
) {
  stop(
    "The inherited PC1-PC2 explained variance is invalid."
  )
}

# ------------------------------------------------------------
# 7. Recalculate and verify the group centroids
# ------------------------------------------------------------

pca_centroids <- pca_scores %>%
  dplyr::group_by(
    Treatment
  ) %>%
  dplyr::summarise(
    PC1 = mean(PC1),
    PC2 = mean(PC2),
    .groups = "drop"
  ) %>%
  dplyr::arrange(
    Treatment
  )

stored_centroids <- stored_centroids %>%
  dplyr::mutate(
    Treatment = factor(
      as.character(Treatment),
      levels = required_treatments
    )
  ) %>%
  dplyr::arrange(
    Treatment
  )

if (
  nrow(pca_centroids) != 2L ||
  nrow(stored_centroids) != 2L ||
  anyNA(stored_centroids[["Treatment"]]) ||
  !identical(
    as.character(pca_centroids[["Treatment"]]),
    required_treatments
  ) ||
  !identical(
    as.character(stored_centroids[["Treatment"]]),
    required_treatments
  )
) {
  stop(
    "The recalculated or stored PCA centroid table is invalid."
  )
}

centroid_comparison <- all.equal(
  as.matrix(
    pca_centroids[
      ,
      c(
        "PC1",
        "PC2"
      ),
      drop = FALSE
    ]
  ),
  as.matrix(
    stored_centroids[
      ,
      c(
        "PC1",
        "PC2"
      ),
      drop = FALSE
    ]
  ),
  tolerance = 1e-12,
  check.attributes = FALSE
)

if (!isTRUE(centroid_comparison)) {
  stop(
    "The recalculated centroids do not reproduce the definitive ",
    "Script 019 centroids."
  )
}

# ------------------------------------------------------------
# 8. Helper function for 95% normal-theory data ellipses
# ------------------------------------------------------------

calculate_data_ellipse <- function(
    group_scores,
    treatment_label,
    level,
    critical_value,
    radius,
    segments
) {

  score_matrix <- as.matrix(
    group_scores[
      ,
      c(
        "PC1",
        "PC2"
      ),
      drop = FALSE
    ]
  )

  storage.mode(score_matrix) <- "double"

  if (
    nrow(score_matrix) < 3L ||
    !identical(
      ncol(score_matrix),
      2L
    ) ||
    any(!is.finite(score_matrix))
  ) {
    stop(
      treatment_label,
      ": invalid PC1-PC2 score matrix."
    )
  }

  group_centre <- colMeans(
    score_matrix
  )

  group_covariance <- stats::cov(
    score_matrix
  )

  if (
    !is.matrix(group_covariance) ||
    !identical(
      dim(group_covariance),
      c(
        2L,
        2L
      )
    ) ||
    any(!is.finite(group_covariance)) ||
    max(
      abs(
        group_covariance -
          t(group_covariance)
      )
    ) > numeric_tolerance
  ) {
    stop(
      treatment_label,
      ": invalid covariance matrix."
    )
  }

  covariance_eigen <- eigen(
    group_covariance,
    symmetric = TRUE
  )

  eigenvalues <- as.numeric(
    covariance_eigen[["values"]]
  )

  eigenvectors <- covariance_eigen[["vectors"]]

  if (
    length(eigenvalues) != 2L ||
    any(!is.finite(eigenvalues)) ||
    any(eigenvalues <= numeric_tolerance) ||
    !is.matrix(eigenvectors) ||
    !identical(
      dim(eigenvectors),
      c(
        2L,
        2L
      )
    ) ||
    any(!is.finite(eigenvectors))
  ) {
    stop(
      treatment_label,
      ": covariance matrix is not positive definite."
    )
  }

  semi_axis_lengths <- radius *
    sqrt(
      eigenvalues
    )

  ellipse_transform <- eigenvectors %*%
    diag(
      semi_axis_lengths,
      nrow = 2L,
      ncol = 2L
    )

  theta <- seq(
    from = 0,
    to = 2 * pi,
    length.out = segments
  )

  unit_circle <- rbind(
    cos(theta),
    sin(theta)
  )

  ellipse_matrix <- t(
    ellipse_transform %*%
      unit_circle
  )

  ellipse_matrix <- sweep(
    ellipse_matrix,
    MARGIN = 2,
    STATS = group_centre,
    FUN = "+"
  )

  colnames(ellipse_matrix) <- c(
    "PC1",
    "PC2"
  )

  if (
    !identical(
      dim(ellipse_matrix),
      c(
        segments,
        2L
      )
    ) ||
    any(!is.finite(ellipse_matrix))
  ) {
    stop(
      treatment_label,
      ": invalid ellipse coordinates were generated."
    )
  }

  mahalanobis_squared <- stats::mahalanobis(
    x = score_matrix,
    center = group_centre,
    cov = group_covariance,
    inverted = FALSE
  )

  if (
    length(mahalanobis_squared) != nrow(score_matrix) ||
    any(!is.finite(mahalanobis_squared)) ||
    any(mahalanobis_squared < -numeric_tolerance)
  ) {
    stop(
      treatment_label,
      ": invalid squared Mahalanobis distances were generated."
    )
  }

  inside_ellipse <- mahalanobis_squared <=
    critical_value +
      sqrt(
        .Machine$double.eps
      )

  major_axis_vector <- eigenvectors[
    ,
    1
  ]

  major_axis_angle_degrees <- (
    atan2(
      major_axis_vector[2],
      major_axis_vector[1]
    ) *
      180 /
      pi
  )

  if (major_axis_angle_degrees < 0) {
    major_axis_angle_degrees <- major_axis_angle_degrees + 180
  }

  if (major_axis_angle_degrees >= 180) {
    major_axis_angle_degrees <- major_axis_angle_degrees - 180
  }

  ellipse_area <- pi *
    semi_axis_lengths[1] *
    semi_axis_lengths[2]

  covariance_condition_number <- eigenvalues[1] /
    eigenvalues[2]

  ellipse_coordinates <- tibble::tibble(
    Treatment = factor(
      treatment_label,
      levels = required_treatments
    ),
    Ellipse_order = seq_len(
      segments
    ),
    PC1 = as.numeric(
      ellipse_matrix[
        ,
        "PC1"
      ]
    ),
    PC2 = as.numeric(
      ellipse_matrix[
        ,
        "PC2"
      ]
    )
  )

  ellipse_summary <- tibble::tibble(
    Treatment = factor(
      treatment_label,
      levels = required_treatments
    ),
    Group_n = nrow(score_matrix),
    Ellipse_level = level,
    Chi_square_critical_value = critical_value,
    Centre_PC1 = group_centre[1],
    Centre_PC2 = group_centre[2],
    Covariance_PC1 = group_covariance[1, 1],
    Covariance_PC2 = group_covariance[2, 2],
    Covariance_PC1_PC2 = group_covariance[1, 2],
    Correlation_PC1_PC2 = stats::cor(
      score_matrix[
        ,
        1
      ],
      score_matrix[
        ,
        2
      ],
      method = "pearson"
    ),
    Largest_covariance_eigenvalue = eigenvalues[1],
    Smallest_covariance_eigenvalue = eigenvalues[2],
    Covariance_condition_number =
      covariance_condition_number,
    Semi_major_axis = semi_axis_lengths[1],
    Semi_minor_axis = semi_axis_lengths[2],
    Major_axis_angle_degrees =
      major_axis_angle_degrees,
    Ellipse_area_PC1_PC2 = ellipse_area,
    Observations_inside_ellipse = sum(
      inside_ellipse
    ),
    Observations_outside_ellipse = sum(
      !inside_ellipse
    ),
    Observed_percentage_inside = 100 *
      mean(
        inside_ellipse
      ),
    Interpretation = paste0(
      "95% normal-theory data ellipse; not a confidence region ",
      "for the centroid"
    )
  )

  covariance_long <- tibble::tibble(
    Treatment = factor(
      treatment_label,
      levels = required_treatments
    ),
    Row_variable = c(
      "PC1",
      "PC1",
      "PC2",
      "PC2"
    ),
    Column_variable = c(
      "PC1",
      "PC2",
      "PC1",
      "PC2"
    ),
    Covariance = c(
      group_covariance[1, 1],
      group_covariance[1, 2],
      group_covariance[2, 1],
      group_covariance[2, 2]
    )
  )

  list(
    coordinates = ellipse_coordinates,
    summary = ellipse_summary,
    covariance_matrix = group_covariance,
    covariance_long = covariance_long,
    mahalanobis_squared = mahalanobis_squared,
    inside_ellipse = inside_ellipse
  )
}

# ------------------------------------------------------------
# 9. Calculate the two independent-population ellipses
# ------------------------------------------------------------

ellipse_results_by_group <- vector(
  mode = "list",
  length = length(required_treatments)
)

names(ellipse_results_by_group) <- required_treatments

for (treatment_i in required_treatments) {

  group_scores_i <- pca_scores[
    as.character(
      pca_scores[["Treatment"]]
    ) == treatment_i,
    ,
    drop = FALSE
  ]

  expected_group_n_i <- if (
    treatment_i == "Control"
  ) {
    expected_control_n
  } else {
    expected_stress_n
  }

  if (nrow(group_scores_i) != expected_group_n_i) {
    stop(
      treatment_i,
      ": unexpected group size before ellipse calculation."
    )
  }

  ellipse_results_by_group[[treatment_i]] <-
    calculate_data_ellipse(
      group_scores = group_scores_i,
      treatment_label = treatment_i,
      level = ellipse_level,
      critical_value = ellipse_critical_value,
      radius = ellipse_radius,
      segments = ellipse_segments
    )
}

ellipse_coordinates <- dplyr::bind_rows(
  lapply(
    ellipse_results_by_group,
    function(result_i) {
      result_i[["coordinates"]]
    }
  )
) %>%
  dplyr::arrange(
    Treatment,
    Ellipse_order
  )

ellipse_summary <- dplyr::bind_rows(
  lapply(
    ellipse_results_by_group,
    function(result_i) {
      result_i[["summary"]]
    }
  )
) %>%
  dplyr::arrange(
    Treatment
  )

covariance_long <- dplyr::bind_rows(
  lapply(
    ellipse_results_by_group,
    function(result_i) {
      result_i[["covariance_long"]]
    }
  )
) %>%
  dplyr::arrange(
    Treatment,
    Row_variable,
    Column_variable
  )

if (
  nrow(ellipse_coordinates) !=
    length(required_treatments) *
      ellipse_segments ||
  nrow(ellipse_summary) !=
    length(required_treatments) ||
  nrow(covariance_long) != 8L ||
  any(!is.finite(ellipse_coordinates[["PC1"]])) ||
  any(!is.finite(ellipse_coordinates[["PC2"]])) ||
  any(!is.finite(ellipse_summary[["Ellipse_area_PC1_PC2"]])) ||
  any(ellipse_summary[["Ellipse_area_PC1_PC2"]] <= 0)
) {
  stop(
    "The combined ellipse outputs are invalid."
  )
}

ellipse_centres <- ellipse_summary[
  ,
  c(
    "Treatment",
    "Centre_PC1",
    "Centre_PC2"
  ),
  drop = FALSE
] %>%
  dplyr::rename(
    PC1 = Centre_PC1,
    PC2 = Centre_PC2
  ) %>%
  dplyr::arrange(
    Treatment
  )

ellipse_centre_comparison <- all.equal(
  as.matrix(
    ellipse_centres[
      ,
      c(
        "PC1",
        "PC2"
      ),
      drop = FALSE
    ]
  ),
  as.matrix(
    pca_centroids[
      ,
      c(
        "PC1",
        "PC2"
      ),
      drop = FALSE
    ]
  ),
  tolerance = 1e-12,
  check.attributes = FALSE
)

if (!isTRUE(ellipse_centre_comparison)) {
  stop(
    "The ellipse centres do not reproduce the corrected PCA centroids."
  )
}

# ------------------------------------------------------------
# 10. Figure
# ------------------------------------------------------------

pc1_label <- paste0(
  "PC1 (",
  format(
    round(
      pc1_percent,
      1
    ),
    nsmall = 1
  ),
  "%)"
)

pc2_label <- paste0(
  "PC2 (",
  format(
    round(
      pc2_percent,
      1
    ),
    nsmall = 1
  ),
  "%)"
)

p_ellipse <- ggplot2::ggplot() +
  ggplot2::geom_polygon(
    data = ellipse_coordinates,
    mapping = ggplot2::aes(
      x = PC1,
      y = PC2,
      group = Treatment,
      fill = Treatment,
      colour = Treatment
    ),
    alpha = 0.16,
    linewidth = 0.75
  ) +
  ggplot2::geom_point(
    data = pca_scores,
    mapping = ggplot2::aes(
      x = PC1,
      y = PC2,
      colour = Treatment
    ),
    size = 2.0,
    alpha = 0.68
  ) +
  ggplot2::geom_point(
    data = pca_centroids,
    mapping = ggplot2::aes(
      x = PC1,
      y = PC2,
      colour = Treatment
    ),
    shape = 4,
    size = 5.0,
    stroke = 1.4
  ) +
  ggplot2::labs(
    x = pc1_label,
    y = pc2_label,
    colour = NULL,
    fill = NULL
  ) +
  ggplot2::coord_equal() +
  ggplot2::theme_classic(
    base_size = 12
  ) +
  ggplot2::theme(
    panel.border = ggplot2::element_rect(
      colour = "black",
      fill = NA,
      linewidth = 0.6
    ),
    legend.position = "top",
    axis.text = ggplot2::element_text(
      colour = "black"
    ),
    axis.title = ggplot2::element_text(
      colour = "black"
    ),
    plot.background = ggplot2::element_rect(
      fill = "white",
      colour = NA
    ),
    panel.background = ggplot2::element_rect(
      fill = "white",
      colour = NA
    )
  )

print(
  p_ellipse
)

